import numpy as np; exec("class Solution:\n    def forward_and_backward(self, x, W1, b1, W2, b2, y_true):\n        x=np.array(x);W1=np.array(W1);b1=np.array(b1);W2=np.array(W2);b2=np.array(b2);y_true=np.array(y_true)\n        z1=np.dot(W1,x)+b1;a1=np.maximum(0,z1);z2=np.dot(W2,a1)+b2\n        loss=np.mean((z2-y_true)**2)\n        d_z2=2*(z2-y_true)/len(y_true);dW2=np.outer(d_z2,a1);db2=d_z2\n        d_a1=np.dot(W2.T,d_z2);d_z1=d_a1*(z1>0);dW1=np.outer(d_z1,x);db1=d_z1\n        return {'loss':round(float(loss),4),'dW1':np.round(dW1,4).tolist(),'db1':np.round(db1,4).tolist(),'dW2':np.round(dW2,4).tolist(),'db2':np.round(db2,4).tolist()}")